package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchProducts handles product search with category filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	sortField := r.URL.Query().Get("sort")

	if category == "" {
		http.Error(w, "category required", http.StatusBadRequest)
		return
	}

	// Build query with parameterized price but dynamic category and sort
	var queryBuilder strings.Builder
	queryBuilder.WriteString("SELECT id, name, price, description FROM products WHERE category = '")
	queryBuilder.WriteString(category)
	queryBuilder.WriteString("'")

	if minPrice != "" {
		queryBuilder.WriteString(" AND price >= $1")
	}

	// Sort field validation - only allow known columns
	allowedSorts := map[string]bool{"name": true, "price": true, "id": true}
	if sortField != "" && allowedSorts[sortField] {
		queryBuilder.WriteString(" ORDER BY " + sortField)
	}

	query := queryBuilder.String()
	log.Printf("Executing query: %s", query)

	var rows *sql.Rows
	var err error
	if minPrice != "" {
		rows, err = db.Query(query, minPrice)
	} else {
		rows, err = db.Query(query)
	}
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("["))
	first := true
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		if err := rows.Scan(&id, &name, &price, &description); err != nil {
			continue
		}
		if !first {
			w.Write([]byte(","))
		}
		first = false
		fmt.Fprintf(w, `{"id":%d,"name":"%s","price":%.2f,"description":"%s"}`, id, name, price, description)
	}
	w.Write([]byte("]"))
}

// deleteProduct removes a product - admin only
func deleteProduct(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodDelete {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	productID := r.URL.Query().Get("id")
	// Note: no auth check here, relies on infrastructure layer
	_, err := db.Exec("DELETE FROM products WHERE id = $1", productID)
	if err != nil {
		http.Error(w, "delete failed", http.StatusInternalServerError)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/api/products/delete", deleteProduct)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
